import fnmatch
import os


def walk_glob(root, pattern, follow_symlinks=False, skip_dirs=None):
    """Yield paths under `root` whose base name matches `pattern`.

    Directories named in `skip_dirs` are pruned from the walk, so nothing
    inside them is visited or matched.
    """
    if skip_dirs is None:
        skip_dirs = {".git", "__pycache__", "node_modules"}
    else:
        skip_dirs = set(skip_dirs)

    matches = []
    for dirpath, dirnames, filenames in os.walk(root, followlinks=follow_symlinks):
        dirnames[:] = [d for d in dirnames if d not in skip_dirs]

        for name in filenames:
            if not fnmatch.fnmatch(name, pattern):
                continue
            full = os.path.join(dirpath, name)
            try:
                if os.path.isfile(full):
                    matches.append(full)
            except OSError as exc:
                # A broken symlink or a file deleted mid-walk; the tree is
                # allowed to change under us, so record and keep going.
                print(f"skipping {full}: {exc}")

    matches.sort()
    return matches


def walk_glob_deep(root, pattern, **kwargs):
    """Like `walk_glob`, but `pattern` is matched against the path relative
    to `root`, so it can span separators: "src/**/test_*.py".
    """
    results = []
    for path in walk_glob(root, "*", **kwargs):
        rel = os.path.relpath(path, root)
        if fnmatch.fnmatch(rel, pattern):
            results.append(path)
    return results
